mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  float sphere = length(p) - 1.1;
  float waves = sin(p.x * 6.0 + time * 3.0) * cos(p.y * 6.0) * sin(p.z * 6.0) * 0.12;
  float ring = length(vec2(length(p.xz) - 1.8, p.y)) - 0.08;
  return min(sphere + waves, ring);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.3, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float glow = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    glow += 0.02 / (0.1 + abs(d));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(1.2, 0.45, 0.05) * (0.8 + 0.3 * bass);
  ret = col;
}
